"XWBM5iNXTGijseqtryiwLg","type":"itemLink","children":[{"type":"span","value":"proven to be an effective solution"}]},{"type":"span","marks":["strong"],"value":"."}]}]}},"links":[{"__typename":"BlogArticleRecord","id":"XWBM5iNXTGijseqtryiwLg","slug":"customer-story-api-tul"}]}}]},"comparisonText":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"heading","level":3,"children":[{"type":"span","value":"IMAGE COMPRESSION AND CONVERSION WITHOUT VISIBLE QUALITY LOSS"}]},{"type":"heading","level":2,"children":[{"type":"span","value":"Can you tell the difference?"}]},{"type":"paragraph","children":[{"type":"span","value":"Move the slider to compare the compressed and converted image with the original. \u2028\nThe file size is reduced by more than 85%!"}]}]}}},"comparisonArrow1":"Darker places\u2028stay intact","comparisonArrow2":"Tiniest details\u2028are still there","comparisonArrow3":"Almost no difference in the sunset gradient","comparisonLabelOriginal":"ORIGINAL","comparisonLabelTinify":"TINIFY","analyzerText":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Discover how much Tinify can\n"},{"type":"span","marks":["strong"],"value":"improve your website's performance"},{"type":"span","value":"."}]}]}}},"analyzerPlaceholderText":"Your website location","analyzerButtonText":"Analyze now","ctaText":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"heading","level":3,"children":[{"type":"span","value":"Speed up your \u2028\nwebsite with Tinify"}]},{"type":"paragraph","children":[{"type":"span","value":"Maximize your website’s performance \nand improve SEO rankings with \u2028\nTinify’s image optimization. "}]}]}}},"ctaButton":[{"id":"171800237","label":"Get started now","target":{"__typename":"MenuItemInternalRecord","queryParams":"","anchor":"","page":{"__typename":"CdnOverviewRecord","slug":"/cdn","enSlug":"/cdn"}}}],"questionAndAnswers":[{"id":"M9JJ2shRQv-66b-jcfADtg","title":"General","faqEntry":[{"id":"aX_CrZndTNeOluKqymmawQ","question":"Why should I compress my images for my website?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Optimizing your images with the TinyPNG algorithm brings several benefits to your website. "}]},{"type":"paragraph","children":[{"type":"span","value":"TinyPNG reduces file sizes by up to 80% without sacrificing quality, leading to "},{"type":"span","marks":["strong"],"value":"faster page loads"},{"type":"span","value":". This optimization is essential for keeping user attention and ensuring an enjoyable user experience. Additionally, it "},{"type":"span","marks":["strong"],"value":"minimizes bandwidth usage"},{"type":"span","value":", making your website more efficient and cost-effective. "}]},{"type":"paragraph","children":[{"type":"span","value":"Image compression also plays a role in SEO, as efficiently compressed images contribute to faster page speeds and "},{"type":"span","marks":["strong"],"value":"improve your website's search engine ranking"},{"type":"span","value":"."}]}]}},"links":[]}},{"id":"SdUXgq3pR0C0HANa8cXBjA","question":"Does TinyPNG support WebP images?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Yes, TinyPNG "},{"type":"span","marks":["strong"],"value":"supports WebP"},{"type":"span","value":" images. Our compression feature enables users to achieve the most optimal results when working with WebP files."}]},{"type":"paragraph","children":[{"type":"span","value":"WebP, a web image file format created by Google, is supported by major browsers such as Chrome, Firefox, Edge and Opera. This format excels in achieving reduced file sizes while maintaining optimal image quality. Consequently, WebP images are "},{"type":"span","marks":["strong"],"value":"smaller in size"},{"type":"span","value":" compared to PNG and JPEG counterparts, contributing to faster website loading times. This is particularly beneficial for your users, ensuring swift page load times and minimizing bandwidth costs, especially for mobile users."}]},{"type":"paragraph","children":[{"type":"span","value":"It’s worth highlighting that despite WebP’s inherent size advantages, Tinify’s optimization can"},{"type":"span","marks":["strong"],"value":" further decrease the file size"},{"type":"span","value":". The intelligent algorithm ensures that there are no visible differences while more savings are made."}]}]}},"links":[]}},{"id":"ULXfqPuVRHavHd4Hu0B7qw","question":"What does TinyPNG do?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"TinyPNG uses smart lossy compression techniques to reduce the file size of your WEBP, AVIF, JPEG and PNG files. By selectively decreasing the number of colors in the image, fewer bytes are required to store the data. The effect is nearly invisible but it makes a very large difference in file size!"}]}]}},"links":[]}},{"id":"HvTtOYIpTHigIJWNqFn9WQ","question":"What file formats does TinyPNG support for image compression?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Currently, Tinify supports "},{"type":"span","marks":["strong"],"value":"JPEG XL (JXL)"},{"type":"span","value":", "},{"type":"span","marks":["strong"],"value":"AVIF, WebP, JPG, PNG "},{"type":"span","value":"and"},{"type":"span","marks":["strong"],"value":" APNG"},{"type":"span","value":" (animated PNG)."}]},{"type":"paragraph","children":[{"type":"span","value":"We are continuously working to expand our portfolio to include additional formats in the future."}]}]}},"links":[]}},{"id":"C5PdckH7SsGQJVJiBEM0ow","question":"Why do I get an optimized JPG when I upload a HEIC image?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"HEIC is an image format that compresses photos very efficiently, but it is not widely supported by many other devices and platforms. To ensure your images work everywhere, TinyPNG automatically converts HEIC files to JPG, a widely accepted format."}]},{"type":"paragraph","children":[{"type":"span","value":"If you prefer a next-gen format like AVIF, you can easily convert it with the online optimizer. Avif images offer better quality and smaller file sizes than other formats. The best format you choose depends on how you plan to use the images."}]}]}},"links":[]}},{"id":"A7S2Kp3dQpKAzEO7LaQTFQ","question":"Is the privacy of my images ensured?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"At Tinify, your privacy is our top priority. Rest assured, only you have access to the images you upload. We retain them for a maximum of 48 hours, after which they are permanently deleted."}]},{"type":"paragraph","children":[{"type":"span","value":"For additional details on privacy, please refer to our "},{"item":"UZ2fOAdHSeGezPPrFZZZJA","meta":[],"type":"itemLink","children":[{"type":"span","marks":["underline"],"value":"Terms of Use"}]},{"type":"span","value":", specifically sections 8 and 9. These sections provide comprehensive information on privacy policies and data processing operations."}]}]}},"links":[{"__typename":"TermsOfUseRecord","id":"UZ2fOAdHSeGezPPrFZZZJA","slug":"/terms"}]}},{"id":"WXGO6pxlRLSHlP3sgIyfJQ","question":"Why did you create TinyPNG?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"We frequently use PNG images but were frustrated with the load times. We created TinyPNG in our quest to make our websites faster and more fun to use with the best compression.\n\nSince then, we’ve continued to grow. In 2014, we added intelligent compression for JPEG images. In 2016, we introduced support for animated PNG. And today, we also support modern image formats like WebP and AVIF, helping developers and businesses stay ahead with next-generation optimization.\n\nCompressing images with the website is free for everyone, and we like to keep it that way! If you like TinyPNG, please contribute by making a donation."}]}]}},"links":[]}}]},{"id":"Pshys8zaTruphe5YaqbEfQ","title":"How does it work","faqEntry":[{"id":"Kyo0xDCfS0iBaLpFPbt4_g","question":"What is lossy compression?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","marks":["strong"],"value":"Lossy compression"},{"type":"span","value":" is a method that reduces file sizes by removing certain data from the original file, often resulting in a loss of quality. "}]},{"type":"paragraph","children":[{"type":"span","value":"However, with TinyPNG’s "},{"type":"span","marks":["strong"],"value":"intelligent algorithm"},{"type":"span","value":", we can achieve large savings without visible quality loss. Tinify uses smart lossy compression techniques to decrease the size of your pictures and make them "},{"type":"span","marks":["strong"],"value":"ready for web use"},{"type":"span","value":"."}]}]}},"links":[]}},{"id":"QYVHxM__TmST6K0VJxLPKQ","question":"How does TinyPNG optimize images without losing quality? ","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Our compression engine employs a "},{"type":"span","marks":["strong"],"value":"smart algorithm"},{"type":"span","value":" to determine the best optimization levels tailored to each image's unique content, considering factors like colors, textures, and patterns. Unlike one-size-fits-all approaches, we understand that each image requires specific compression settings for "},{"type":"span","marks":["strong"],"value":"optimal results"},{"type":"span","value":"."}]},{"type":"paragraph","children":[{"type":"span","value":"Take, for example, the selective decrease in the number of colors within an image. This strategic approach not only maintains image quality but also significantly reduces the number of bytes needed to store the data. Thanks to our intelligent algorithm, the optimization process results in nearly invisible effects on the image while making a "},{"type":"span","marks":["strong"],"value":"big difference in file size"},{"type":"span","value":"."}]}]}},"links":[]}},{"id":"Jb28UJLrQQKQe4rgWd47vQ","question":"How does PNG image compression work?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"When you upload a PNG (Portable Network Graphics) file, similar colors in your image are intelligently combined. This technique, called "},{"type":"span","marks":["emphasis"],"value":"quantization"},{"type":"span","value":", reduces the number of colors without noticeably affecting quality. As a result, 24-bit PNG files can be converted into much smaller 8-bit indexed color images.\n\nWe also remove unnecessary metadata to further reduce file size. The result? Optimized PNG files with 100% support for transparency. Have your cake and eat it too!"}]}]}},"links":[]}},{"id":"FWHlSchnSHy5p4JysD8vMQ","question":"Why should I use TinyPNG to optimize my PNG files?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"PNG is useful because it’s the only widely supported format that can store partially transparent images. The format uses compression, but the files can still be large. Use TinyPNG to shrink images for your apps and sites. It will use less bandwidth and load faster."}]}]}},"links":[]}},{"id":"A1RNLbpeSBe7vKlvqJj2KQ","question":"How does JPG image compression work?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"When you upload a JPEG file, the image is analyzed. Textures, patterns and colors are automatically identified. The encoder creates an optimally compressed JPEG file based on that information. The final result is compared with the original and fine-tuned. Distracting JPEG artifacts are minimized without big sacrifices in file size. Unnecessary metadata is stripped as well. You will get an optimal image, every time!"}]}]}},"links":[]}},{"id":"Crw33zzXT1yJmIpCwQZFEw","question":"How does TinyPNG manage metadata during the compression process?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"TinyPNG "},{"type":"span","marks":["strong"],"value":"removes all unnecessary metadata"},{"type":"span","value":" from the images to reduce file size."}]},{"type":"paragraph","children":[{"type":"span","value":"Please note that this process might result in the optimized image appearing with a different dpi (dots per inch) or color profile, as default values will be applied in the absence of metadata."}]},{"type":"paragraph","children":[{"type":"span","value":"If there's a need to preserve specific metadata from your images, consider exploring our Developer API. The API offers an option to retain certain metadata such as copyright, location, and creation date. Further details about this feature can be found in the "},{"item":"KV7vOx6eQsyfNXhLHXOJcw","meta":[{"id":"anchor","value":"preserving-metadata"}],"type":"itemLink","children":[{"type":"span","marks":["underline"],"value":"API documentation"}]},{"type":"span","value":"."}]}]}},"links":[{"__typename":"MockSlugRecord","id":"KV7vOx6eQsyfNXhLHXOJcw","slug":"/developers/reference"}]}},{"id":"eEFAiaFrTDSxGd7HAh1J9w","question":"Are the optimized images supported everywhere?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"The files produced by TinyPNG are displayed perfectly on all modern browsers including mobile devices.\n\nStill need to support Internet Explorer 6? It normally ignores PNG transparency and displays a solid background color. With TinyPNG the background becomes transparent again. Binary transparency without any workarounds!"}]}]}},"links":[]}},{"id":"Fo4u4AyYQJuZJLrj_kCT9A","question":"Is it safe to use animated PNG?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Chrome, Firefox, Safari, and now Microsoft Edge all support APNG. Only Internet Explorer does not support the format yet.\n\nApple added animated stickers to iMessage with the release of iOS 10. If you want to create and compress stickers under 500 KB, take a look at the iMessage Panda sticker example on "},{"url":"https://github.com/tinify/iMessage-Panda-sticker","meta":[{"id":"target","value":"_blank"}],"type":"link","children":[{"type":"span","marks":["underline"],"value":"GitHub"}]},{"type":"span","value":"."}]}]}},"links":[]}}]},{"id":"RbFJ1zzuQXivxFqNmUlV1Q","title":"Web compressor","faqEntry":[{"id":"Q0XJgHK-R2atD25Dw8-IPA","question":"Can I compress my images for free? ","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Certainly! Feel free to use the "},{"type":"span","marks":["strong"],"value":"drag-and-drop web optimizer "},{"type":"span","value":"at "},{"item":"166934935","meta":[],"type":"itemLink","children":[{"type":"span","marks":["underline"],"value":"tinypng.com"}]},{"type":"span","value":". Free users have the flexibility to upload up to 20 images at once, each with a maximum size of 5MB.\n\nFor those looking to convert images to other file types, you can freely convert up to 3 images.\n\nIf you find that you need more capacity, feel free to explore our "},{"type":"span","marks":["strong"],"value":"Web Pro"},{"type":"span","value":" and "},{"type":"span","marks":["strong"],"value":"Web Ultra "},{"item":"d6-QX9b6RHm-yHRQ8_6G6Q","type":"itemLink","children":[{"type":"span","marks":["underline"],"value":"subscriptions"}]},{"type":"span","value":". These subscriptions provide additional benefits for optimizing your images beyond the limits of our free offering."}]}]}},"links":[{"__typename":"HomepageContentRecord","id":"166934935","slug":"/"},{"__typename":"WebPricingRecord","id":"d6-QX9b6RHm-yHRQ8_6G6Q","slug":"/pricing/web"}]}},{"id":"N21jwZ3tR6u3kV6EuJOlSA","question":"How can I reduce the file size of my image with the online web tool?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"The TinyPNG compressor is a "},{"type":"span","marks":["strong"],"value":"user-friendly"},{"type":"span","value":" tool designed for effortlessly minimizing the file size of your AVIF, WebP, PNG, and JPG images. Simply "},{"type":"span","marks":["strong"],"value":"drag and drop"},{"type":"span","value":" your pictures onto the web interface, and let our intelligent algorithm compress them for optimal results."}]}]}},"links":[]}},{"id":"TbZPddcOT92T9qkWHs_CDQ","question":"Should I convert my web images to WebP?","answer":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"WebP has become a popular choice on the web, offering impressive performance in terms of both quality and size. Utilizing "},{"type":"span","marks":["strong"],"value":"Tinify's image converter"},{"type":"span","value":", you can effortlessly transform your JPG and PNG images into the "},{"type":"span","marks":["strong"],"value":"WebP format"},{"type":"span","value":"."}]},{"type":"paragraph","children":[{"type":"span","value":"However, it's crucial not to dismiss other formats entirely, as they may still outperform WebP in certain scenarios. The Tinify online tool simplifies the process of finding the ideal image version for optimal p